// ─── File: CpuDiagnosticsDemo.java ───
// Reproduces regex-driven high CPU and locates it with a sampling probe.
// Each class below would be its own file in a real project.
package com.bank.cpu;

import java.util.logging.*;

public class CpuDiagnosticsDemo {

    private static final Logger log = Logger.getLogger("Cpu");

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        handler.setLevel(Level.ALL);
        log.setUseParentHandlers(false);
        log.addHandler(handler);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) throws Exception {
        NarrationValidator validator = new NarrationValidator();
        SamplingProfiler profiler = new SamplingProfiler();

        // A crafted narration that triggers catastrophic backtracking in the BAD pattern.
        String evilInput = "Rajesh salary " + "a".repeat(30) + "!";

        // STEP 1 — confirm high CPU, separate from GC (GC quiet here)
        log.info("GC quiet → CPU is in application code, profile to find hot method");

        // STEP 2 — profile while the hot workload runs
        profiler.start();
        long start = System.currentTimeMillis();
        for (int i = 0; i < 50; i++) {
            validator.isValidBad(evilInput);          // pathological: exponential backtracking
        }
        long badMs = System.currentTimeMillis() - start;
        profiler.stop();
        log.severe(() -> "BAD regex validated 50 narrations in " + badMs + "ms (CPU pinned)");
        profiler.printHotMethods();                    // flame-graph-like summary

        // STEP 3 — the fix: a safe pattern + bounded input
        long start2 = System.currentTimeMillis();
        for (int i = 0; i < 50; i++) validator.isValidSafe(evilInput);
        long goodMs = System.currentTimeMillis() - start2;
        log.info(() -> "SAFE regex validated 50 narrations in " + goodMs + "ms (CPU normal)");
    }
}

// ─── validate/NarrationValidator.java ───
class NarrationValidator {
    // BAD: nested quantifiers (a+)+ cause catastrophic backtracking on certain inputs.
    private static final java.util.regex.Pattern BAD =
            java.util.regex.Pattern.compile("^(([A-Za-z ]+)+)!$");
    // SAFE: linear, anchored, no nested quantifier; input also length-bounded by caller.
    private static final java.util.regex.Pattern SAFE =
            java.util.regex.Pattern.compile("^[A-Za-z ]+!$");

    boolean isValidBad(String narration) { return BAD.matcher(narration).matches(); }

    boolean isValidSafe(String narration) {
        if (narration.length() > 140) return false;    // bound input: no blowup possible
        return SAFE.matcher(narration).matches();
    }
}

// ─── probe/SamplingProfiler.java ───
// Minimal stand-in for async-profiler / JFR: samples the main thread's top frame.
class SamplingProfiler {
    private static final Logger log = Logger.getLogger("Cpu");
    private final java.util.Map<String, Integer> samples = new java.util.concurrent.ConcurrentHashMap<>();
    private volatile boolean running;
    private Thread sampler;
    private final Thread target = Thread.currentThread();

    void start() {
        running = true;
        sampler = new Thread(() -> {
            while (running) {
                StackTraceElement[] st = target.getStackTrace();   // sample the hot thread
                if (st.length > 0) {
                    String top = st[0].getClassName() + "." + st[0].getMethodName();
                    samples.merge(top, 1, Integer::sum);
                }
                try { Thread.sleep(5); } catch (InterruptedException e) { return; }
            }
        });
        sampler.setDaemon(true);
        sampler.start();
    }

    void stop() { running = false; }

    void printHotMethods() {
        log.severe(() -> "HOT METHODS (by sample count, widest = hottest):");
        samples.entrySet().stream()
                .sorted((a, b) -> b.getValue() - a.getValue())
                .limit(5)
                .forEach(e -> log.severe(() -> "   " + e.getValue() + " samples  " + e.getKey()));
    }
}

class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT %2$-7s %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
